def choose_architecture(needs_action, needs_current_docs):
    if needs_action and needs_current_docs:
        return "Hybrid: ADK orchestrates the task, RAG supplies grounded facts"
    if needs_action:
        return "ADK: a procedural, tool-using agent"
    if needs_current_docs:
        return "RAG: retrieval over your documents"
    return "A plain model call may be enough"


# Examples from the lesson
print(choose_architecture(needs_action=True,  needs_current_docs=False))  # IT triage
print(choose_architecture(needs_action=False, needs_current_docs=True))   # legal lookup
print(choose_architecture(needs_action=True,  needs_current_docs=True))   # legal co-pilot
